// AUTO-GENERATED by Claude Code
// Purpose: the chat box's history, as a terminal's: ArrowUp in the empty box brings back the last
//          message sent (slash commands and "@" prints too), ArrowUp again the one before;
//          ArrowDown goes forward, and past the newest back to the empty box. Only while the box
//          is empty or still shows a recalled message untouched: once you edit it, the arrows
//          move the cursor as usual. Kept in this browser (localStorage, the newest 100; a
//          message sent twice in a row is kept once).
(() => {
  const BOX = 'textarea[name="prompt"]';
  const KEY = "smash.chatHistory";
  const MAX = 100;

  const load = () => {
    try {
      const saved = JSON.parse(localStorage.getItem(KEY) || "[]");
      return Array.isArray(saved) ? saved.filter((item) => typeof item === "string") : [];
    } catch {
      return [];
    }
  };
  const save = (items) => {
    try {
      localStorage.setItem(KEY, JSON.stringify(items.slice(-MAX)));
    } catch {
      // storage full or off: the history just isn't kept
    }
  };

  // where we are while going through the history: an index into it, null = not browsing
  let at = null;

  const show = (box, text) => {
    box.value = text;
    box.selectionStart = box.selectionEnd = text.length;
    // colour a slash command or a mention in it (assets/slash.js). Not an input event: that
    // would open the slash or "@" list, whose arrows would then take over
    if (window.recolourChatBox) window.recolourChatBox();
  };

  // sending: remember the message (capture: before the form is emptied)
  document.addEventListener("submit", (event) => {
    const box = event.target instanceof Element && event.target.querySelector(BOX);
    if (!box) return;
    const text = box.value.trim();
    at = null;
    if (!text) return;
    const items = load();
    if (items[items.length - 1] !== text) save([...items, text]);
  }, true);

  document.addEventListener("keydown", (event) => {
    const box = event.target;
    if (!(box instanceof Element) || !box.matches(BOX)) return;
    if (event.key !== "ArrowUp" && event.key !== "ArrowDown") return;
    if (event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
    // an open list (slash commands, "@" variables) owns the arrows
    if (document.querySelector("[data-slash-menu].is-open, .mention-menu.is-open")) return;
    const items = load();
    // still browsing only if the box shows the recalled message as it was
    if (at !== null && box.value !== items[at]) at = null;
    if (at === null && (box.value !== "" || event.key === "ArrowDown")) return;
    if (!items.length) return;
    event.preventDefault();
    if (event.key === "ArrowUp") {
      at = at === null ? items.length - 1 : Math.max(at - 1, 0);
      show(box, items[at]);
    } else if (at >= items.length - 1) {
      at = null;
      show(box, "");
    } else {
      at += 1;
      show(box, items[at]);
    }
  }, true);
})();
